class.description:
A [DialogueSpeaker] describes one speaker of a game. Lines refer to it by [member id]: [member DialogueLineNode.speaker], [member SubtitleSegment.speaker] (subtitle files carry it as text, for example the SubRip name tag [code]ANNA: Hello[/code] or the WebVTT voice tag [code]<v Anna>[/code]) and the keys of [member SubtitleLabel.speaker_colors] all use the same id.
The speakers of a project are collected in a [DialogueSpeakers] resource, set in [member ProjectSettings.audio/subtitles/speakers] and available as [member SubtitleServer.speakers]. A disguised speaker ("???") is a speaker of its own with another id.
[codeblocks]
[gdscript]
var anna = DialogueSpeaker.new()
anna.id = &"anna"
anna.display_name = "SPEAKER_ANNA" # A translation key or a plain name.
anna.portrait_path = "res://portraits/anna.png"
anna.color = Color.CORAL
anna.tts_persona = load("res://voices/anna.tres")

var speakers = DialogueSpeakers.new()
speakers.add_speaker(anna)
SubtitleServer.speakers = speakers

$Name.text = anna.get_translated_name()
$Portrait.texture = anna.load_portrait()
TTSServer.speak_with_persona("Hello!", anna.id)
[/gdscript]
[csharp]
var anna = new DialogueSpeaker();
anna.Id = "anna";
anna.DisplayName = "SPEAKER_ANNA"; // A translation key or a plain name.
anna.PortraitPath = "res://portraits/anna.png";
anna.Color = Colors.Coral;
anna.TtsPersona = GD.Load<TtsPersona>("res://voices/anna.tres");

var speakers = new DialogueSpeakers();
speakers.AddSpeaker(anna);
SubtitleServer.Speakers = speakers;

GetNode<Label>("Name").Text = anna.GetTranslatedName();
GetNode<TextureRect>("Portrait").Texture = anna.LoadPortrait();
TtsServer.SpeakWithPersona("Hello!", anna.Id);
[/csharp]
[/codeblocks]
